content.text:
    if (level == 2 && epoch != null) {
        long[] stats = epochs.get(epoch);
        if (stats == null) {
            stats = new long[] {pn, pn, 0L};
            epochs.put(epoch, stats);
        }
        if (pn < stats[0]) {
            stats[0] = pn;
        }
        if (pn > stats[1]) {
            stats[1] = pn;
        }
        stats[2]++;
        if (epoch == currentEpoch + 1) {
            currentEpoch = epoch;
        }
    }
}

private boolean epochAllowed(long annotation) {
    if (annotation == currentEpoch) {
        return true;
    }
    if (currentEpoch > 0 && annotation == currentEpoch - 1) {
        return true;
    }
    return annotation == currentEpoch + 1 && annotation <= MAX62;
}

private boolean epochOrderValid(long epoch, long pn) {
    for (Map.Entry<Long, long[]> entry : epochs.entrySet()) {
        long other = entry.getKey();
        if (other == epoch) {
            continue;
        }
        long[] stats = entry.getValue();
        if (stats[2] == 0) {
            continue;
        }
        if (epoch > other) {
            if (pn <= stats[1]) {
                return false;
            }
        } else if (pn >= stats[0]) {
            return false;
        }
    }
    return true;
}

/** Index of the issued, unretired local connection id matching {@code dcid} or -1. */
private int matchLocalCid(byte[] dcid) {
    for (int index = 0; index < localCids.length; index++) {
        if (localRetired[index]) {
            continue;
        }
        if (Arrays.equals(localCids[index], dcid)) {
            return index;
        }
    }
    return -1;
}

// ------------------------------------------------------------------ frame processing

/**
 * Decodes and applies all frames of one packet.
 *
 * @return the payload offset of a connection close frame or -1
 */
private int processFrames(Envelope envelope, List<Frame> frames, Txn txn, int destination)
        throws FrameError {
    byte[] payload = envelope.payload;
    int level = envelope.level;
    Cursor cursor = new Cursor(payload);
    if (payload.length == 0) {
        throw new FrameError(FRAME_ENCODING_ERROR, 0);
    }
    int closeOffset = -1;
    while (cursor.pos < payload.length) {
        int start = cursor.pos;
        long type = cursor.varint(start);
        if (cursor.lastLength != QuicVarint.size(type)) {
            throw new FrameError(FRAME_ENCODING_ERROR, start);
        }
        if (!isSupportedFrameType(type)) {
            throw new FrameError(FRAME_ENCODING_ERROR, start);
        }
        checkFrameLevel(type, level, start);
        Frame frame = decodeFrame(type, cursor, start);
        applyFrame(frame, level, txn, destination, start);
        frames.add(frame);
        if (frame.type == 0x1c || frame.type == 0x1d) {
            closeOffset = start;
            break;
        }
    }
    return closeOffset;
}

/** True for the frame types of the profile. */
private static boolean isSupportedFrameType(long type) {
    if (type < 0 || type > 0x1e) {
        return type == 0x30 || type == 0x31;
    }
    return true;
}

private static void checkFrameLevel(long type, int level, int offset) throws FrameError {
    switch ((int) type) {
        case 0x00:
        case 0x01:
        case 0x02:
        case 0x03:
        case 0x06:
        case 0x1c:
            return;
        case 0x07:
        case 0x1e:
            throw new FrameError(PROTOCOL_VIOLATION, offset);
        default:
            if (level != 2) {
                throw new FrameError(PROTOCOL_VIOLATION, offset);
            }
            return;
    }
}

private Frame decodeFrame(long type, Cursor cursor, int start) throws FrameError {
    Frame frame = new Frame((int) type);
    switch ((int) type) {
        case 0x00:
        case 0x01:
            break;
