            frame.ackDelay = cursor.varint(start);
            long count = cursor.varint(start);
            frame.ackFirst = cursor.varint(start);
            if (frame.ackFirst > frame.ackLargest) {
                throw new FrameError(FRAME_ENCODING_ERROR, start);
            }
            int remaining = cursor.data.length - cursor.pos;
            if (count > remaining / 2) {
                throw new FrameError(FRAME_ENCODING_ERROR, start);
            }
